Compare squares at both ends and fill the result from right to left. This handles empty arrays, duplicates, and negative numbers without changing the input. Time: O(n); output space: O(n), with O(1) auxiliary space.

```javascript
function solve(nums) {
  const result = new Array(nums.length);
  let left = 0;
  let right = nums.length - 1;

  for (let i = nums.length - 1; i >= 0; i--) {
    const leftSquare = nums[left] * nums[left];
    const rightSquare = nums[right] * nums[right];

    if (leftSquare > rightSquare) {
      result[i] = leftSquare;
      left++;
    } else {
      result[i] = rightSquare;
      right--;
    }
  }

  return result;
}
```

