Count values in a, consume matching occurrences from b, then sort numerically. This preserves each shared value exactly the minimum of its two occurrence counts and does not modify either input.

```javascript
function solve(a, b) {
  const counts = new Map();
  const result = [];

  for (const value of a) {
    counts.set(value, (counts.get(value) || 0) + 1);
  }

  for (const value of b) {
    const remaining = counts.get(value) || 0;
    if (remaining > 0) {
      result.push(value);
      counts.set(value, remaining - 1);
    }
  }

  result.sort((x, y) => x - y);
  return result;
}
```

